import Foundation

/// 五语言 UI 字典。严格跟随 `@AppStorage("selectedLanguage")`，不依赖 Bundle 语言包回退。
enum L10n {
    static func t(_ key: String) -> String {
        let code = AppLanguageCode.load().resolvedContentCode()
        if let row = table[key] {
            if let value = row[code], !value.isEmpty { return value }
            if let en = row["en"], !en.isEmpty { return en }
            if let ja = row["ja"], !ja.isEmpty { return ja }
        }
        return key
    }

    private static let table: [String: [String: String]] = [
        "%@ %lld": ["en": "%1$@ %2$lld", "ja": "%1$@ %2$lld", "zh-Hans": "%1$@ %2$lld", "vi": "%1$@ %2$lld", "ko": "%1$@ %2$lld"],
        "%@, %@": ["en": "%1$@, %2$@", "ja": "%1$@, %2$@", "zh-Hans": "%1$@, %2$@", "vi": "%1$@, %2$@", "ko": "%1$@, %2$@"],
